/* Playable follow-up missions. All state uses the existing guided-slice archive. */
const SOUND_ADVENTURES = [
  { id:'r-beat-lab-v1', learner:'Robby', subject:'math', title:'The Beat Bridge', desc:'Hear a rhythm, repair a missing beat, and loop equal groups to cross the moon.', skill:'B.E.S.T. MA.1.NSO.1.1, MA.1.NSO.2.2 · counting and adding within 20', slice:'beat-math-robby' },
  { id:'t-beat-lab-v1', learner:'Tommy', subject:'math', title:'The Loop Reactor', desc:'Copy a pulse, remove a note, and prove how repeated loops become equal groups.', skill:'B.E.S.T. MA.2.AR.3.2 · equal groups, arrays, and repeated addition', slice:'beat-math-tommy' },
  { id:'r-sound-song-v1', learner:'Robby', subject:'reading', title:'The Cat and the Sound Song', desc:'Give each sound a note, build short-a words, and sing a sentence to save the ham.', skill:'B.E.S.T. ELA.K.F.1.3, ELA.1.F.1.3 · segmenting and encoding CVC words', slice:'phonics-song' },
  { id:'t-forest-branch-v1', learner:'Tommy', subject:'reading', title:'Cheesia and the Shadow Cape', desc:'Name a forest pet, follow two short paths, and choose how to rescue the seedlings.', skill:'B.E.S.T. ELA.2.R.1.1, SC.2.L.17.1 · plot, evidence, and living things’ needs', slice:'forest-branch' }
];
for (const lesson of SOUND_ADVENTURES) {
  GUIDED_SLICES[lesson.id] = { ...lesson, type:'guided-slice' };
  LESSONS[lesson.learner][lesson.subject].splice(1, 0, GUIDED_SLICES[lesson.id]);
}

const BEAT_MATH_EVIDENCE = {
  Robby: ['Matched a four-step heard rhythm with notes and rests.', 'Counted three sounding beats.', 'Repaired a missing beat in the pattern.', 'Played equal loops and represented them with repeated addition.', 'Removed a beat and represented equal groups of two.'],
  Tommy: ['Matched a five-step heard rhythm with notes and rests.', 'Counted four sounding beats.', 'Repaired a missing beat in the pattern.', 'Played equal loops and modeled them as an array and repeated addition.', 'Removed a beat and represented equal groups of three.']
};
const PHONICS_SONG_EVIDENCE = ['Identified /ă/ as the medial sound in cat.', 'Encoded three short-a CVC words from ordered phonemes.', 'Sequenced a decodable three-word sentence.', 'Changed an initial phoneme while preserving /ă/.', 'Encoded map, named a pet, and chose a story ending.'];
const FOREST_EVIDENCE = ['Identified the hero and named a story pet.', 'Selected a route that changed the next story scene.', 'Compared a plant’s need for light and water with an animal’s needs.', 'Used the wet soil and dark cover as causal evidence.', 'Chose an ending and defended it with a science reason.'];
const SOUND_ADVENTURE_EVIDENCE = {'beat-math-robby':BEAT_MATH_EVIDENCE.Robby,'beat-math-tommy':BEAT_MATH_EVIDENCE.Tommy,'phonics-song':PHONICS_SONG_EVIDENCE,'forest-branch':FOREST_EVIDENCE};
function syncAdventureEvidence() {
  const session = getSliceSession(), record = state.progress.find(item => item.learner === state.current && item.lessonId === activeSlice.id);
  const evidence = SOUND_ADVENTURE_EVIDENCE[activeSlice.slice];
  if (!session.bossPassed || !record?.snapshot || !evidence) return;
  record.snapshot.completedStages = [...session.completedStages];
  record.snapshot.evidence = evidence.filter((item,index) => session.completedStages.includes(index)).join(' ');
  saveState();
}

let soundAdventureTimers = [];
function soundAdventureStop() { soundAdventureTimers.forEach(clearTimeout); soundAdventureTimers = []; }
function playAdventureBeat(pattern, repeats = 1) {
  soundAdventureStop();
  const steps = Array.from({ length: repeats }, () => pattern).flat();
  steps.forEach((on, index) => {
    const delay = index * .38;
    playTone(on ? 392 : 145, on ? .20 : .06, delay);
    soundAdventureTimers.push(setTimeout(() => {
      document.querySelectorAll('.beat-pad').forEach(pad => pad.classList.toggle('sounding', Number(pad.dataset.slot) === index % pattern.length));
    }, delay * 1000));
  });
  soundAdventureTimers.push(setTimeout(() => document.querySelectorAll('.beat-pad').forEach(pad => pad.classList.remove('sounding')), steps.length * 380));
}
const beatPattern = learner => learner === 'Robby' ? [1,0,1,1] : [1,1,0,1,1];
const beatCount = learner => learner === 'Robby' ? 3 : 4;
const beatRepeats = (learner, difficulty) => learner === 'Robby' ? ({normal:2,hard:3,master:4}[difficulty] || 2) : ({normal:4,hard:5,master:6}[difficulty] || 4);
function beatPads(pattern, selected, label, action, removed = -1) {
  return `<div class="beat-pads" role="group" aria-label="${label}">${pattern.map((on, i) => `<button type="button" class="beat-pad ${selected?.includes(i) ? 'lit' : ''} ${removed === i ? 'removed' : ''}" data-slot="${i}" data-${action}="${i}" aria-pressed="${action === 'beat-boss-remove' ? removed === i : !!selected?.includes(i)}" ${action === 'none' ? 'disabled' : ''}><span>${i + 1}</span><b>${selected?.includes(i) ? '♪' : '·'}</b></button>`).join('')}</div>`;
}
function beatDone(session, index, text, next) { return session.completedStages.includes(index) ? completePanel(index, text, next) : ''; }
function renderBeatMathStage(session) {
  const a = session.answers, who = activeSlice.learner, pattern = beatPattern(who), count = beatCount(who), repeats = beatRepeats(who,session.difficulty);
  if (session.bossPassed && session.stage === 4) return `<div class="victory-panel"><span>♫</span><div><p>Rhythm Reactor complete</p><h3>${who === 'Robby' ? 'The moon bridge danced in time.' : 'The loop reactor stopped arguing with arithmetic.'}</h3><p>${session.completedStages.length} of 5 parts checked. Your completed work and boss result were saved.</p><b>${DIFFICULTY_POINTS[session.difficulty]} points · ${session.difficulty}</b></div></div>`;
  if (session.stage === 0) return `${stageHeading('Part 1 · Remember','Echo the beat','Tap Listen. Turn on the pads that sound bright. Quiet low clicks are rests. Then test your copy.','♫')}
    <div class="sound-bench"><button class="sound-play" data-play-pattern>▶ Listen to the beat</button>${beatPads(pattern,a.beatCopy || [],'Copy the sounding beats','toggle-beat-copy')}<button class="primary-action" data-check-beat-copy>Test my beat</button></div>${beatDone(session,0,'You matched notes and rests by ear.','Count the notes')}<p class="practice-status" id="sliceStatus">Each numbered space is one equal time step.</p>`;
  if (session.stage === 1) return `${stageHeading('Part 2 · Learn','How many notes?','A rest uses time, but it is not a sounding note. Count what you hear.','♪')}
    <div class="sound-bench"><button class="sound-play" data-play-pattern>▶ Hear it again</button>${beatPads(pattern,pattern.map((v,i)=>v?i:-1).filter(i=>i>=0),'The source rhythm','none')}<div class="number-choices" role="group" aria-label="Number of sounding notes">${[count-1,count,count+1].map(n=>`<button data-beat-count="${n}">${n} notes</button>`).join('')}</div></div>${beatDone(session,1,`${count} notes sound; the other space is a rest.`,'Find the missing beat')}<p class="practice-status" id="sliceStatus">Try tapping along on the table.</p>`;
  if (session.stage === 2) {
    const missing = who === 'Robby' ? 2 : 3, shown = pattern.map((v,i)=>i===missing?0:v), selection = a.beatMissing === undefined ? [] : [a.beatMissing];
    return `${stageHeading('Part 3 · Practice','The missing beat','One bright note fell out. Listen to the original, then tap the numbered gap that should sound.','?')}
      <div class="sound-bench"><button class="sound-play" data-play-pattern>▶ Hear the original</button>${beatPads(shown,[...shown.map((v,i)=>v?i:-1).filter(i=>i>=0),...selection],'Choose the missing note','beat-missing')}<button class="primary-action" data-check-beat-missing>Repair the rhythm</button></div>${beatDone(session,2,'The missing beat is back in place.','Loop the beat')}<p class="practice-status" id="sliceStatus">Compare the whole pattern, not just its last sound.</p>`;
  }
  if (session.stage === 3) {
    const total = count * repeats, equation = Array(repeats).fill(count).join(' + ') + ` = ${total}`;
    return `${stageHeading('Part 4 · Apply','Loop laboratory',`The pattern has ${count} sounding notes. Play ${repeats} equal loops. How many sounding notes altogether?`, '↻')}
      <div class="sound-bench"><button class="sound-play" data-play-loops="${repeats}">▶ Repeat ${repeats} times</button><div class="loop-array" aria-label="${repeats} equal groups of ${count} notes">${Array.from({length:repeats},(_,i)=>`<div><small>Loop ${i+1}</small>${Array(count).fill('<span>♪</span>').join('')}</div>`).join('')}</div><div class="number-choices" role="group" aria-label="Total sounding notes">${[total-count,total,total+count].map(n=>`<button data-loop-total="${n}">${n}</button>`).join('')}</div><p class="beat-equation">${Array(repeats).fill(count).join(' + ')} = ${session.completedStages.includes(3)?total:'?'}</p></div>${beatDone(session,3,`Each loop keeps the same ${count} notes, so ${equation}.`,'Face the Beat Boss')}<p class="practice-status" id="sliceStatus">The array shows each whole loop as an equal group.</p>`;
  }
  const remove = who === 'Robby' ? 2 : 1, newCount = count-1, total = newCount * repeats;
  return `${stageHeading('Part 5 · Boss','Take one away',`The boss stole the ${who === 'Robby' ? 'second' : 'second'} sounding note. Tap that note, then find the new total across ${repeats} equal loops. You can challenge the boss at any time.`, '★')}
    <div class="sound-bench"><button class="sound-play" data-play-pattern>▶ Hear the original</button>${beatPads(pattern,pattern.map((v,i)=>v?i:-1).filter(i=>i>=0),'Select the second sounding note','beat-boss-remove',a.beatBossRemoved)}<div class="number-choices" role="group" aria-label="Notes after removing one from every loop">${[total-repeats,total,total+repeats].map(n=>`<button data-boss-beat-total="${n}" aria-pressed="${a.beatBossTotal===n}">${n}</button>`).join('')}</div><p class="beat-equation">${Array(repeats).fill(newCount).join(' + ')} = ?</p><button class="boss-finish" data-check-beat-boss>Repair the bridge + save evidence</button></div><p class="practice-status" id="sliceStatus">Removing one note from every loop changes each equal group by one.</p>`;
}
function beatMathTextbook() { return `<article class="mini-textbook"><header><span>Rhythm Reactor field guide</span><h3>Sound has a count</h3></header><section><h4>Notes and rests</h4><p>Each pad is one equal time step. A note sounds; a rest is silent space. Listen, tap, and count the notes.</p></section><section><h4>Repeat a whole pattern</h4><p>A loop repeats all its steps. Three notes played twice make <b>3 + 3 = 6</b> sounding notes.</p></section><section><h4>Change each group</h4><p>If you remove one note from each loop, every equal group shrinks by one. Draw rows of notes to see the relationship.</p></section><section><h4>Grown-up prompt</h4><p>Ask, “What stays the same in every loop?” and “How did the total change?”</p></section></article>`; }
function bindBeatMathStage(session, root) {
  const a=session.answers, who=activeSlice.learner, pattern=beatPattern(who), repeats=beatRepeats(who,session.difficulty), count=beatCount(who);
  const fail=message=>{session.support.hints++;saveState();root.querySelector('#sliceStatus').textContent=message};
  root.querySelectorAll('[data-play-pattern]').forEach(b=>b.addEventListener('click',()=>playAdventureBeat(pattern)));
  root.querySelector('[data-play-loops]')?.addEventListener('click',()=>playAdventureBeat(pattern,repeats));
  root.querySelectorAll('[data-toggle-beat-copy]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.toggleBeatCopy);a.beatCopy||=[];a.beatCopy=a.beatCopy.includes(i)?a.beatCopy.filter(x=>x!==i):[...a.beatCopy,i];playTone(392,.16);saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-beat-copy]')?.addEventListener('click',()=>{if(pattern.every((v,i)=>(a.beatCopy||[]).includes(i)===!!v)){markStageComplete(0);renderGuidedSlice()}else fail('Listen for the quiet rests. Each bright note has its own pad.')});
  root.querySelectorAll('[data-beat-count]').forEach(b=>b.addEventListener('click',()=>{if(Number(b.dataset.beatCount)===count){markStageComplete(1);renderGuidedSlice()}else fail('Count only the bright notes. The low clicks mark rests.') }));
  root.querySelectorAll('[data-beat-missing]').forEach(b=>b.addEventListener('click',()=>{a.beatMissing=Number(b.dataset.beatMissing);playTone(392,.16);saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-beat-missing]')?.addEventListener('click',()=>{if(a.beatMissing===(who==='Robby'?2:3)){markStageComplete(2);renderGuidedSlice()}else fail('That gap does not match the original rhythm. Listen once more.')});
  root.querySelectorAll('[data-loop-total]').forEach(b=>b.addEventListener('click',()=>{if(Number(b.dataset.loopTotal)===count*repeats){markStageComplete(3);renderGuidedSlice()}else fail('Count each equal row of notes, then add the rows together.') }));
  root.querySelectorAll('[data-beat-boss-remove]').forEach(b=>b.addEventListener('click',()=>{a.beatBossRemoved=Number(b.dataset.beatBossRemove);saveState();renderGuidedSlice()}));
  root.querySelectorAll('[data-boss-beat-total]').forEach(b=>b.addEventListener('click',()=>{a.beatBossTotal=Number(b.dataset.bossBeatTotal);saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-beat-boss]')?.addEventListener('click',()=>{if(a.beatBossRemoved===(who==='Robby'?2:1)&&a.beatBossTotal===(count-1)*repeats){a.beatEquation=Array(repeats).fill(count-1).join(' + ')+` = ${(count-1)*repeats}`;finishGuidedSlice()}else fail('Find the second sounding note, remove one from every loop, then recount the groups.')});
}

const SONG_PITCH={c:261.63,s:293.66,m:329.63,a:392,t:440,p:523.25};
const SONG_PHONEME={c:'/k/',s:'/s/',m:'/m/',a:'/ă/',t:'/t/',p:'/p/'};
const SONG_WORDS=['cat','sat','mat'];
function playSoundSong(letters) { soundAdventureStop(); [...letters].forEach((letter,i)=>{const pitch=SONG_PITCH[letter.toLowerCase()];if(pitch)playTone(pitch,.30,i*.35)}); }
function songNotes(word) {return `<div class="phoneme-song" role="img" aria-label="${esc(word)} sound song">${[...word.replace(/[^a-z]/gi,'')].map((letter,i)=>`<span style="--song-pitch:${i}"><b>${esc(letter)}</b><small>${SONG_PHONEME[letter.toLowerCase()]||''}</small></span>`).join('')}</div>`;}
function songLetterChoices(word,difficulty) {return [...new Set([...word,...(difficulty==='master'?['i','o']:difficulty==='hard'?['i']:[])])];}
function renderPhonicsSongStage(session) {
  const a=session.answers;
  if(session.bossPassed && session.stage===4){const name=esc(a.petName||'Puff');return `<div class="victory-panel"><span>♫</span><div><p>Sound song saved</p><h3>${a.songEnding==='cat'?`The cat and ${name} shared the ham.`:`The ram and ${name} found a new map.`}</h3><p>${session.completedStages.length} of 5 parts checked. Your completed word work and ending choice were saved.</p><b>${DIFFICULTY_POINTS[session.difficulty]} points · ${session.difficulty}</b></div></div>`;}
  if(session.stage===0)return `${stageHeading('Part 1 · Remember','A sound in the middle','The cat hums three pitches to open a snack gate. Say the phoneme under each note, then find the short-a middle sound.','♫')}<div class="sound-bench"><p class="song-story">The cat had the ham. Sam ran. The cat sang: <b>c · a · t</b>. The gate lit up!</p>${songNotes('cat')}<button class="sound-play" data-play-song="cat">▶ Play notes and hear cat</button><div class="number-choices">${['i','a','o'].map(x=>`<button data-song-vowel="${x}">${x}</button>`).join('')}</div></div>${beatDone(session,0,'You found /ă/ in the middle of cat.','Build word songs')}<p class="practice-status" id="sliceStatus">Pitch marks each sound’s place. Say /k/ /ă/ /t/ and blend: cat.</p>`;
  if(session.stage===1){const round=a.songRound||0,word=SONG_WORDS[Math.min(round,2)],built=a.songLetters||[];return `${stageHeading('Part 2 · Learn',round>=3?'Three word songs ready':'Put sounds together',round>=3?'Same middle vowel, different first sounds.':`Build ${word} by placing one letter on each note. Word ${round+1} of 3.`, '♪')}${round>=3?beatDone(session,1,'You encoded cat, sat, and mat.','Make a sentence song'):`<div class="sound-bench"><button class="sound-play" data-say-song-word="${word}">▶ Hear ${word}</button>${songNotes(word)}<div class="phoneme-pods song-pods">${[0,1,2].map(i=>`<button data-remove-song-letter="${i}">${esc(built[i]||'·')}</button>`).join('')}</div><div class="letter-bank">${songLetterChoices(word,session.difficulty).map(letter=>`<button data-add-song-letter="${letter}">${letter}</button>`).join('')}</div><button class="primary-action" data-check-song-word="${word}">Play my word song</button></div>`}<p class="practice-status" id="sliceStatus">Each letter records one sound. Tap a filled note to undo it.</p>`;}
  if(session.stage===2){const words=a.songSentenceWords||[];return `${stageHeading('Part 3 · Practice','Sentence song','Put three word beats in order to tell what happened. Then sing the whole sentence.','♬')}<div class="sound-bench"><p class="song-story">The cat sat. What did the cat do?</p><div class="sentence-pads">${words.map((w,i)=>`<button data-remove-song-word="${i}">${esc(w)}</button>`).join('')||'<span>Build your sentence here</span>'}</div><div class="number-choices">${['sat.','A','cat'].filter(w=>!words.includes(w)).map(w=>`<button data-add-song-word="${esc(w)}">${esc(w)}</button>`).join('')}</div><button class="primary-action" data-check-song-sentence>Sing my sentence</button></div>${beatDone(session,2,'A cat sat. You made three word beats tell one idea.','Change the first sound')}<p class="practice-status" id="sliceStatus">Tap a word in your sentence to move it back.</p>`;}
  if(session.stage===3)return `${stageHeading('Part 4 · Apply','Change one note','The cat sat. Sam wants a mat. Keep /ă/ and /t/. What first sound makes mat?','↗')}<div class="sound-bench">${songNotes('sat')}<p class="beat-equation">sat → ?at</p><div class="number-choices">${['r','m','p'].map(x=>`<button data-song-change="${x}">${x}</button>`).join('')}</div></div>${beatDone(session,3,'You changed /s/ to /m/ and kept /ă/ /t/.','Face the Song Boss')}<p class="practice-status" id="sliceStatus">One changed sound changes the word and the story.</p>`;
  const built=a.songBossLetters||[];return `${stageHeading('Part 5 · Boss','The snack gate','Spell map with three sound notes. Then name a pet and choose who finds the ham.','★')}<div class="sound-bench"><button class="sound-play" data-say-song-word="map">▶ Hear map</button>${songNotes('map')}<div class="phoneme-pods song-pods">${[0,1,2].map(i=>`<button data-remove-song-boss-letter="${i}">${esc(built[i]||'·')}</button>`).join('')}</div><div class="letter-bank">${songLetterChoices('map',session.difficulty).map(x=>`<button data-add-song-boss-letter="${x}">${x}</button>`).join('')}</div><label class="pet-name">Name your forest pet <input id="songPetName" maxlength="20" value="${esc(a.petName||'Puff')}" aria-label="Pet name"></label><fieldset class="branch-choices"><legend>Choose an ending</legend><button data-song-ending="cat" aria-pressed="${a.songEnding==='cat'}">The cat shares the ham with your pet.</button><button data-song-ending="ram" aria-pressed="${a.songEnding==='ram'}">The ram and your pet find a new map.</button></fieldset><button class="boss-finish" data-check-song-boss>Sing the ending + save</button></div><p class="practice-status" id="sliceStatus">The boss is open whenever you are ready.</p>`;
}
function phonicsSongTextbook(){return `<article class="mini-textbook"><header><span>Sound Stage field guide</span><h3>Letters can sing</h3></header><section><h4>Three sound places</h4><p>Say cat slowly: /k/ /ă/ /t/. The colored pitches help you hear first, middle, and last. They do not replace speaking each sound.</p></section><section><h4>Keep the middle</h4><p>Cat, sat, and mat share short <b>a</b>. Swap the first sound to change the word.</p></section><section><h4>Words make a sentence</h4><p><b>A cat sat.</b> has three word beats and tells one complete idea. Read the words after singing them.</p></section></article>`;}
function bindPhonicsSongStage(session,root){const a=session.answers;const fail=m=>{session.support.hints++;saveState();root.querySelector('#sliceStatus').textContent=m};
  root.querySelectorAll('[data-play-song]').forEach(b=>b.addEventListener('click',()=>{playSoundSong(b.dataset.playSong);speakText(b.dataset.playSong,.83)}));
  root.querySelectorAll('[data-say-song-word]').forEach(b=>b.addEventListener('click',()=>{playSoundSong(b.dataset.saySongWord);speakText(b.dataset.saySongWord,.83)}));
  root.querySelectorAll('[data-song-vowel]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.songVowel==='a'){markStageComplete(0);renderGuidedSlice()}else fail('Hear the middle sound in cat again: /ă/.')}));
  root.querySelectorAll('[data-add-song-letter]').forEach(b=>b.addEventListener('click',()=>{a.songLetters||=[];if(a.songLetters.length<3)a.songLetters.push(b.dataset.addSongLetter);playTone(SONG_PITCH[b.dataset.addSongLetter]||330,.18);saveState();renderGuidedSlice()}));
  root.querySelectorAll('[data-remove-song-letter]').forEach(b=>b.addEventListener('click',()=>{a.songLetters?.splice(Number(b.dataset.removeSongLetter),1);saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-song-word]')?.addEventListener('click',event=>{const word=event.currentTarget.dataset.checkSongWord;if((a.songLetters||[]).join('')===word){playSoundSong(word);a.songRound=(a.songRound||0)+1;a.songLetters=[];if(a.songRound>=3)markStageComplete(1);saveState();renderGuidedSlice()}else fail('Stretch the word. One sound goes on each note.')});
  root.querySelectorAll('[data-add-song-word]').forEach(b=>b.addEventListener('click',()=>{a.songSentenceWords||=[];a.songSentenceWords.push(b.dataset.addSongWord);saveState();renderGuidedSlice()}));
  root.querySelectorAll('[data-remove-song-word]').forEach(b=>b.addEventListener('click',()=>{a.songSentenceWords?.splice(Number(b.dataset.removeSongWord),1);saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-song-sentence]')?.addEventListener('click',()=>{if((a.songSentenceWords||[]).join(' ')==='A cat sat.'){a.songSentence='A cat sat.';playSoundSong('catsat');speakText(a.songSentence,.85);markStageComplete(2);renderGuidedSlice()}else fail('A sentence starts with A, then tells who, then what happened.')});
  root.querySelectorAll('[data-song-change]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.songChange==='m'){playSoundSong('mat');markStageComplete(3);renderGuidedSlice()}else fail('Which first sound turns sat into mat?')}));
  root.querySelectorAll('[data-add-song-boss-letter]').forEach(b=>b.addEventListener('click',()=>{a.songBossLetters||=[];if(a.songBossLetters.length<3)a.songBossLetters.push(b.dataset.addSongBossLetter);playTone(SONG_PITCH[b.dataset.addSongBossLetter]||330,.18);saveState();renderGuidedSlice()}));
  root.querySelectorAll('[data-remove-song-boss-letter]').forEach(b=>b.addEventListener('click',()=>{a.songBossLetters?.splice(Number(b.dataset.removeSongBossLetter),1);saveState();renderGuidedSlice()}));
  root.querySelector('#songPetName')?.addEventListener('input',e=>{a.petName=e.target.value.slice(0,20);saveState()});
  root.querySelectorAll('[data-song-ending]').forEach(b=>b.addEventListener('click',()=>{a.petName=root.querySelector('#songPetName')?.value.trim().slice(0,20)||'Puff';a.songEnding=b.dataset.songEnding;saveState();renderGuidedSlice()}));
  root.querySelector('[data-check-song-boss]')?.addEventListener('click',()=>{a.petName=root.querySelector('#songPetName')?.value.trim().slice(0,20)||'Puff';if((a.songBossLetters||[]).join('')==='map'&&a.songEnding){playSoundSong('map');finishGuidedSlice()}else fail('Build m-a-p in order, then choose one story ending.')});
}

function forestPet(a){return esc(a.petName?.trim()||'Puff')}
function forestRead(text){return `<button class="sound-play" data-read-forest="${esc(text)}">▶ Read this scene to me</button>`}
function renderForestStage(session){const a=session.answers,pet=forestPet(a);
  if(session.bossPassed && session.stage===4){const ending=a.forestEnding==='open'?`${pet} sneezed, the cape flew up, and sunlight reached the seedlings. Cheesia called it “the smallest rescue team in the forest.”`:`Cheesia carried the seedlings into a sunny clearing. ${pet} carried one leaf and demanded a medal.`;return `<div class="victory-panel storm-victory"><span>🌱</span><div><p>Noodlewood saved</p><h3>${ending}</h3><p>${session.completedStages.length} of 5 parts checked. Your ending and science reason were saved.</p><b>${DIFFICULTY_POINTS[session.difficulty]} points · ${session.difficulty}</b></div></div>`;}
  if(session.stage===0){const scene=`Cheesia lived in Noodlewood, a forest where the wind sometimes answered her whistles. One morning, a villain called Gravy dropped a huge black cape over the young plants. The leaves went dark. The soil was still wet. “I have defeated the forest with fashion,” Gravy announced. His cape had a price tag on it.`;return `${stageHeading('Part 1 · Remember','The shadow falls','One short scene. Meet the hero, spot the problem, and name your pet before the chase.','🌲')}<article class="forest-scene"><p>${scene}</p>${forestRead(scene)}<label class="pet-name">Name Cheesia’s forest pet <input id="forestPetName" maxlength="20" value="${pet}" aria-label="Forest pet name"></label><fieldset class="branch-choices"><legend>Who is trying to help the plants?</legend><button data-forest-hero="Cheesia">Cheesia</button><button data-forest-hero="Gravy">Gravy</button></fieldset></article>${beatDone(session,0,'You met the hero and named her companion.','Choose a path')}<p class="practice-status" id="sliceStatus">The pet travels with you in the next scene.</p>`;}
  if(session.stage===1){const scene=`Cheesia and ${pet} reached a fork. One path ran under the cape toward the roots. The other climbed into the branches toward the leaves. “Both look suspicious,” said ${pet}. “Especially the one with a sign that says NOT SUSPICIOUS.”`;return `${stageHeading('Part 2 · Learn','The fork in the forest','Choose where to investigate. Your choice changes the next scene.','↗')}<article class="forest-scene"><p>${scene}</p>${forestRead(scene)}<div class="branch-choices" role="group" aria-label="Choose a forest path"><button data-forest-route="roots" aria-pressed="${a.forestRoute==='roots'}">Follow the roots below the cape</button><button data-forest-route="leaves" aria-pressed="${a.forestRoute==='leaves'}">Climb to the leaves above the cape</button></div></article>${beatDone(session,1,'Your route is saved. The next scene follows your choice.','Investigate the clue')}<p class="practice-status" id="sliceStatus">Both paths can reveal useful evidence.</p>`;}
  if(session.stage===2){const scene=a.forestRoute==='roots'?`${pet} pressed a paw into the soil. Mud squished up between the toes. “Too wet to be a water problem,” Cheesia said. A seedling drooped anyway. Above them, the cape blocked the sun.`:`From a branch, ${pet} saw pale leaves beneath the cape and bright green leaves beyond it. Cheesia checked the ground. Both patches had damp soil. The shady patch had less light.`;return `${stageHeading('Part 3 · Practice','The living clue','Read the clue from your path. Which two things does a growing plant need here?','🔎')}<article class="forest-scene"><p>${scene}</p>${forestRead(scene)}<fieldset class="branch-choices"><legend>Choose the plant’s needs</legend><button data-forest-needs="light-water">Light and water</button><button data-forest-needs="sandwich">A sandwich and a cape</button><button data-forest-needs="only-water">Only water; light cannot matter</button></fieldset></article>${beatDone(session,2,'You named two plant needs and used the wet soil clue.','Explain the cause')}<p class="practice-status" id="sliceStatus">A pet needs food, water, air, and shelter. Plants need light, water, air, and nutrients.</p>`;}
  if(session.stage===3){const scene=`Gravy pointed at the wet soil. “See? I watered them. My cape is innocent!” Cheesia looked at the dark leaves. ${pet} tugged the cape and found a patch of sunlight beneath its edge.`;return `${stageHeading('Part 4 · Apply','Gravy’s almost-clue','The soil is wet, but the leaves are covered. Which clue best explains the drooping seedlings?','◆')}<article class="forest-scene"><p>${scene}</p>${forestRead(scene)}<fieldset class="branch-choices"><legend>Choose the strongest explanation</legend><button data-forest-cause="shade">The cape blocks light the seedlings need, even though the soil is wet.</button><button data-forest-cause="price">The price tag made the cape too expensive.</button><button data-forest-cause="mud">Wet soil proves the plants need no other resources.</button></fieldset></article>${beatDone(session,3,'You used evidence to explain the cause.','Choose the ending')}<p class="practice-status" id="sliceStatus">One true detail may not explain the real problem.</p>`;}
  const scene=`Gravy's cape was tied to a stump. The soil below it was wet, but the leaves were dark. Cheesia could lift the cape with a gust of wind, or move the seedlings to a sunny clearing. ${pet} suggested eating the cape. Cheesia declined.`;
  const prompt=session.difficulty==='normal'?'Explain which plant need your plan restores.':session.difficulty==='hard'?'Explain the plant need and compare one need of your pet.':'Use the wet soil and dark leaves as evidence, then compare a plant need with a pet need.';
  return `${stageHeading('Part 5 · Boss','Choose the rescue',`Pick one ending. ${prompt} The boss is open whenever you are ready.`,'★')}<article class="forest-scene"><p>${scene}</p>${forestRead(scene)}<fieldset class="branch-choices"><legend>What should Cheesia do?</legend><button data-forest-ending="open" aria-pressed="${a.forestEnding==='open'}">Lift the cape so sunlight reaches the seedlings.</button><button data-forest-ending="move" aria-pressed="${a.forestEnding==='move'}">Move the seedlings to a sunny clearing and keep watering them.</button></fieldset><label class="thinking-note">Why will your plan help?<textarea id="forestReason" placeholder="The plants need light because...">${esc(a.forestReason||'')}</textarea></label><button class="boss-finish" data-check-forest-boss>Finish my ending + save</button></article><p class="practice-status" id="sliceStatus">Explain the plant need, not just the magic gust.</p>`;
}
function forestTextbook(){return `<article class="mini-textbook"><header><span>Noodlewood field guide</span><h3>Life beneath the cape</h3></header><section><h4>Plant needs</h4><p>Plants need light, water, air, and nutrients. Roots take in water and nutrients; leaves use light to make food. A magic gust is fantasy, but the plant needs are real.</p></section><section><h4>Animal needs</h4><p>Animals need food, water, air, and shelter. A habitat must help meet those needs.</p></section><section><h4>Read for cause</h4><p>Wet soil tells you water is present. The dark leaves beneath the cape point to a different missing resource: light.</p></section><section><h4>Talk together</h4><p>What was the problem, which clue mattered, and how did your choice change the ending?</p></section></article>`;}
function bindForestStage(session,root){const a=session.answers;const fail=m=>{session.support.hints++;saveState();root.querySelector('#sliceStatus').textContent=m};
  root.querySelectorAll('[data-read-forest]').forEach(b=>b.addEventListener('click',()=>{session.support.readAloud=true;saveState();speakText(b.dataset.readForest,.94)}));
  root.querySelector('#forestPetName')?.addEventListener('input',e=>{a.petName=e.target.value.slice(0,20);saveState()});
  root.querySelectorAll('[data-forest-hero]').forEach(b=>b.addEventListener('click',()=>{a.petName=root.querySelector('#forestPetName')?.value.trim().slice(0,20)||'Puff';if(b.dataset.forestHero==='Cheesia'){markStageComplete(0);renderGuidedSlice()}else fail('Gravy dropped the cape. Who wants to help the seedlings?')}));
  root.querySelectorAll('[data-forest-route]').forEach(b=>b.addEventListener('click',()=>{a.forestRoute=b.dataset.forestRoute;markStageComplete(1);renderGuidedSlice()}));
  root.querySelectorAll('[data-forest-needs]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.forestNeeds==='light-water'){markStageComplete(2);renderGuidedSlice()}else fail('Use the story clue and the field guide: what does a plant need to grow?')}));
  root.querySelectorAll('[data-forest-cause]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.forestCause==='shade'){markStageComplete(3);renderGuidedSlice()}else fail('The soil was wet. What changed when Gravy dropped the cape?')}));
  root.querySelectorAll('[data-forest-ending]').forEach(b=>b.addEventListener('click',()=>{a.forestReason=root.querySelector('#forestReason')?.value||a.forestReason||'';a.forestEnding=b.dataset.forestEnding;saveState();renderGuidedSlice()}));
  root.querySelector('#forestReason')?.addEventListener('input',e=>{a.forestReason=e.target.value;saveState()});
  root.querySelector('[data-check-forest-boss]')?.addEventListener('click',()=>{a.forestReason=root.querySelector('#forestReason')?.value.trim()||'';const size={normal:25,hard:55,master:85}[session.difficulty];const petNamed=a.forestReason.toLowerCase().includes((a.petName||'Puff').toLowerCase());const compare=session.difficulty==='normal'||((/pet|animal/i.test(a.forestReason)||petNamed)&&/water|food|shelter/i.test(a.forestReason));const clue=session.difficulty!=='master'||/soil|leaf|leaves|cape|shade/i.test(a.forestReason);if(a.forestEnding&&a.forestReason.length>=size&&/light|sun/i.test(a.forestReason)&&compare&&clue){finishGuidedSlice()}else fail(session.difficulty==='normal'?'Choose an ending and explain how the plants will get light.':'Explain the light clue and compare a need your pet has with a need the plant has.')});
}
